                clauses.append(clause)
        return clauses

    def compute_lie_algebroid_order(cnf):
        m = len(cnf)
        n = len(cnf[0])
        matrix = [[0] * (n + 1) for _ in range(m)]
        for i, clause in enumerate(cnf):
            for lit in clause:
                if lit > 0:
                    matrix[i][lit - 1] += 1
                else:
                    matrix[i][-1] -= 1
        rank = 0
        for row in matrix:
            if any(row[j] != 0 for j in range(n + 1)):
                rank += 1
        return rank

    def resolution_width(cnf):
        queue = cnf[:]
        seen = set()
        while queue:
            clause = queue.pop(0)
            for lit in clause:
                neg_lit = -lit
                if neg_lit in seen:
                    continue
                seen.add(neg_lit)
                new_clauses = []
                for other_clause in queue:
                    if neg_lit in other_clause:
